<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { createTenant, disableTenant, enableTenant, fetchTenant, fetchTenantPage, fetchTenants, updateTenant } from '@/services/tenant'
import type { Tenant } from '@/types/api'
const rows = ref<Tenant[]>([]); const visible = ref(false); const editing = ref(false); const loading = ref(false)
const form = reactive({ id: 0, tenantCode: '', tenantName: '', contactName: '', contactEmail: '', contactPhone: '' })
async function load() { loading.value = true; try { const page = await fetchTenantPage({ pageNum: 1, pageSize: 100 }); rows.value = page.records; await fetchTenants() } finally { loading.value = false } }
function openCreate() { editing.value = false; Object.assign(form, { id: 0, tenantCode: '', tenantName: '', contactName: '', contactEmail: '', contactPhone: '' }); visible.value = true }
async function openEdit(value: unknown) { const row = value as Tenant; editing.value = true; Object.assign(form, await fetchTenant(row.id)); visible.value = true }
async function save() { if (!form.tenantName || (!editing.value && !form.tenantCode)) return ElMessage.warning('请填写完整租户信息'); const contact = { contactName: form.contactName || undefined, contactEmail: form.contactEmail || undefined, contactPhone: form.contactPhone || undefined }; if (editing.value) await updateTenant({ id: form.id, tenantName: form.tenantName, ...contact }); else await createTenant({ tenantCode: form.tenantCode, tenantName: form.tenantName, ...contact }); visible.value = false; await load() }
async function remove(value: unknown) { const row = value as Tenant; await ElMessageBox.confirm(`确认停用租户 ${row.tenantName}？`); await disableTenant(row.id); await load() }
async function restore(value: unknown) { const row = value as Tenant; await enableTenant(row.id); ElMessage.success('租户已启用'); await load() }
onMounted(load)
</script>
<template><main class="workspace-page"><header class="page-heading"><div><span class="section-kicker">PLATFORM</span><h1>租户管理</h1><p>仅平台运营权限可访问。</p></div><el-button class="primary-action" type="primary" @click="openCreate">新增租户</el-button></header><section class="glass-card module-card"><el-table v-loading="loading" :data="rows"><el-table-column prop="tenantCode" label="编码" /><el-table-column prop="tenantName" label="名称" /><el-table-column prop="contactName" label="联系人" /><el-table-column prop="contactEmail" label="邮箱" /><el-table-column prop="status" label="状态" /><el-table-column label="操作"><template #default="scope"><el-button link @click="openEdit(scope.row)">编辑</el-button><el-button v-if="scope.row.status==='DISABLED'" link type="success" @click="restore(scope.row)">启用</el-button><el-button v-else link type="danger" @click="remove(scope.row)">停用</el-button></template></el-table-column></el-table></section><el-dialog v-model="visible" :title="editing?'编辑租户':'新增租户'" width="540px"><el-form label-position="top"><el-form-item v-if="!editing" label="租户编码"><el-input v-model="form.tenantCode" /></el-form-item><el-form-item label="租户名称"><el-input v-model="form.tenantName" /></el-form-item><el-form-item label="联系人"><el-input v-model="form.contactName" /></el-form-item><el-form-item label="邮箱"><el-input v-model="form.contactEmail" /></el-form-item><el-form-item label="电话"><el-input v-model="form.contactPhone" /></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></main></template>
